# Break My Fix finding 2, generated by Tracefix: bucket_of returns a wrong value.
# Property (docstring): the docstring's example holds: bucket_of(-15, 10) == -10
# Quote: bucket_of(-15, 10) == -10
# Run it with pytest: it fails for as long as the code breaks this property.

from stats.buckets import bucket_of


def test_break_my_fix_2() -> None:
    value = -15
    width = 10
    result = bucket_of(value=value, width=width)
    assert result == (-10)
